<?php require_once __DIR__.'/config/db.php';$token=preg_replace('/[^a-f0-9]/i','',$_GET['token']??'');$q=getDB()->prepare('SELECT * FROM clubs WHERE tv_token=?');$q->execute([$token]);$club=$q->fetch();if(!$club){http_response_code(403);exit('Invalid TV display token.');} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><script src="https://cdn.tailwindcss.com"></script><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.7.2/css/all.min.css"><style>body{background:#000;color:#fff;font-family:Inter,sans-serif}.pulse{animation:pulse 1.4s infinite}@keyframes pulse{50%{opacity:.45}}</style></head><body class="p-8"><header class="flex justify-between items-center border-b border-slate-700 pb-5"><h1 class="text-3xl font-bold"><?=sanitize($club['name'])?></h1><h2 class="text-2xl font-bold tracking-widest">LIVE TABLES</h2><time id="clock" class="text-4xl font-mono text-green-400"></time></header><div class="grid grid-cols-3 gap-8 mt-8"><section class="col-span-2 grid grid-cols-3 gap-4" id="tables"></section><aside class="bg-slate-900 rounded-xl p-5"><h3 class="text-xl font-bold text-amber-300"><i class="fa-solid fa-trophy mr-2"></i>TOP PLAYERS</h3><ol id="board" class="mt-5 space-y-3"></ol></aside></div><footer class="fixed bottom-4 left-8 right-8 overflow-hidden whitespace-nowrap text-slate-400 border-t border-slate-800 pt-3" id="ticker">Welcome to <?=sanitize($club['name'])?></footer><script>const token=<?=json_encode($token)?>;const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));async function load(){let r=await fetch('api/tv_data.php?token='+token),j=await r.json();if(!j.success)return;document.getElementById('tables').innerHTML=j.data.tables.map(t=>`<div class="rounded-xl p-5 border ${t.status==='running'?'border-red-500 bg-red-950/30':t.status==='available'?'border-green-500 bg-green-950/20':'border-amber-500 bg-slate-900'}"><b class="text-6xl">${esc(t.table_number)}</b><span class="float-right uppercase text-sm">${esc(t.table_type)}</span><p class="mt-5 font-bold text-xl ${t.status==='running'?'text-red-400 pulse':t.status==='available'?'text-green-400':'text-amber-400'}">${esc(t.status==='available'?'AVAILABLE':t.player_name||t.player_name_walkin||t.status.toUpperCase())}</p><p class="text-slate-400 mt-2">${esc(t.status)}</p></div>`).join('');document.getElementById('board').innerHTML=j.data.leaderboard.map((p,i)=>`<li class="flex gap-3"><b class="w-6 ${i<3?'text-amber-300':'text-slate-400'}">${i+1}</b><span class="flex-1">${esc(p.name)}</span><b class="text-green-400">Rs. ${Number(p.value).toLocaleString()}</b></li>`).join('')||'<li class="text-slate-500">No completed sessions this week.</li>'}setInterval(load,5000);load();setInterval(()=>clock.textContent=new Date().toLocaleTimeString(),1000);</script></body></html>
